public class Study{static {if(java.lang.System.getProperty("course.initializer.marker")!=null){try{java.nio.file.Files.writeString(java.nio.file.Path.of(java.lang.System.getProperty("course.initializer.marker")),"student initializer executed");}catch(java.io.IOException e){throw new java.lang.RuntimeException(e);}throw new java.lang.IllegalStateException("initializer sentinel");}}public static void transfer(Object source,Object destination,int count){QueueTransfer.transfer((ICharQ)source,(ICharQ)destination,count);}}

class QueueTransfer {public static void transfer(ICharQ source,ICharQ destination,int count){for(int i=0;i<count;i++)destination.put(source.get());}}
